var dataDir = path.join(process.cwd(), ".pgdata");
var pglite = new PGlite(dataDir);
async function initPglite() {
	await pglite.waitReady;
	const tableCheck = await pglite.query("SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'tenants';");
	if (!tableCheck.rows || tableCheck.rows.length === 0) {
		console.log("[DB] Initializing PGlite PostgreSQL tables and seed data...");
		const migrationsDir = path.join(process.cwd(), "src/server/db/migrations");
		if (fs.existsSync(migrationsDir)) {
			const files = fs.readdirSync(migrationsDir).filter((f) => f.endsWith(".sql")).sort();
			for (const file of files) {
				const statements = fs.readFileSync(path.join(migrationsDir, file), "utf-8").split("--> statement-breakpoint");
				for (const stmt of statements) {
					const trimmed = stmt.trim();
					if (trimmed) try {
						await pglite.exec(trimmed);
					} catch (err) {}
				}
			}
		}
		const seedSqlPath = path.join(process.cwd(), "cloud_seed.sql");
		if (fs.existsSync(seedSqlPath)) {
			const seedSql = fs.readFileSync(seedSqlPath, "utf-8");
			await pglite.exec(seedSql);
		}
		console.log("[DB] PGlite database initialized successfully.");
	}
}
initPglite().catch((err) => console.error("[DB Init Error]:", err));
var db = drizzle(pglite, { schema: schema_exports });
